// ------------------------------------------------------
// backend/scripts/add-matwh-external-processing-coating-fields.js
// ------------------------------------------------------
// Adds targetColor/sourceReservationItemId/isAutoGenerated to
// matWhExternalProcessing (models/MatWhExternalProcessing.js) -- Phase 3
// of the 2026-09-22 Materials Warehouse capability audit's mill-finish
// coating workflow. A shortfall's mill-finish goods receipt now
// auto-creates a DRAFT external-processing job (see routes/
// materialsWarehousePurchasing.js's POST /goods-receipts) recording what
// color it's meant to come back as (targetColor) and which reservation
// line it exists for (sourceReservationItemId) -- a storekeeper still
// picks a vendor and explicitly confirms/sends it (routes/
// materialsWarehouseOperations.js's new POST /external-processing/:id/
// confirm-send) before anything actually leaves the store.
//
// Also widens sentDate to nullable -- a draft job has no send event yet,
// unlike every existing row (always created with status:'sent' and a real
// sentDate in the same call). This is a MODIFY, not a plain ADD COLUMN,
// so it's guarded by its own nullability check rather than the
// column-existence check the other fields use, but stays idempotent the
// same way: safe to re-run.
//
// Idempotent (checks INFORMATION_SCHEMA.COLUMNS first), same pattern as
// every other add-matwh-*.js script.
import { sequelizeUtf8 } from "../config/db.js";

const columnExists = async (table, column) => {
    const [rows] = await sequelizeUtf8.query(`
        SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = :table AND COLUMN_NAME = :column
    `, { replacements: { table, column } });
    return rows.length > 0;
};

const addColumnIfMissing = async (table, column, ddl) => {
    if (await columnExists(table, column)) {
        console.log(`- ${table}.${column} already exists, skipping`);
        return;
    }
    await sequelizeUtf8.query(`ALTER TABLE \`${table}\` ADD COLUMN ${ddl}`);
    console.log(`✅ Added ${table}.${column}`);
};

const makeColumnNullableIfNot = async (table, column, ddl) => {
    const [rows] = await sequelizeUtf8.query(`
        SELECT IS_NULLABLE FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = :table AND COLUMN_NAME = :column
    `, { replacements: { table, column } });
    if (rows.length === 0) {
        console.log(`- ${table}.${column} does not exist, skipping nullability change`);
        return;
    }
    if (rows[0].IS_NULLABLE === 'YES') {
        console.log(`- ${table}.${column} is already nullable, skipping`);
        return;
    }
    await sequelizeUtf8.query(`ALTER TABLE \`${table}\` MODIFY ${ddl}`);
    console.log(`✅ Made ${table}.${column} nullable`);
};

const run = async () => {
    try {
        await addColumnIfMissing("matWhExternalProcessing", "targetColor", "`targetColor` VARCHAR(50) NULL");
        await addColumnIfMissing("matWhExternalProcessing", "sourceReservationItemId", "`sourceReservationItemId` INT NULL");
        await addColumnIfMissing("matWhExternalProcessing", "isAutoGenerated", "`isAutoGenerated` TINYINT(1) NOT NULL DEFAULT 0");
        await makeColumnNullableIfNot("matWhExternalProcessing", "sentDate", "`sentDate` DATETIME NULL");
        process.exit(0);
    } catch (err) {
        console.error("❌ Failed to add matWhExternalProcessing coating fields:", err);
        process.exit(1);
    }
};

run();
